22	// escapeJSONString 把文字写成 JSON \uXXXX 转义序列（非 BMP 字符用代理项对，
23	// 引号、反斜杠与控制字符按 JSON 规则转义），得到与直接书写字符同义的 JSON
24	// 字符串内容（不含两侧引号）。
25	func escapeJSONString(s string) string {
26		var b strings.Builder
27		for _, r := range s {
28			switch {
29			case r == '"':
30				b.WriteString(`\"`)
31			case r == '\\':
32				b.WriteString(`\\`)
33			case r < 0x20:
34				fmt.Fprintf(&b, `\u%04X`, r)
35			case r < 0x80:
36				b.WriteRune(r)
37			case r <= 0xFFFF:
38				fmt.Fprintf(&b, `\u%04X`, r)
39			default:
40				r -= 0x10000
41				fmt.Fprintf(&b, `\u%04X\u%04X`, 0xD800+(r>>10), 0xDC00+(r&0x3FF))
42			}
43		}
44		return b.String()
45	}
