47	// cliSpecialJSON 按写法把文字写入 JSON 字符串字面量：direct 直接书写字符，
48	// escaped 把非 ASCII 与控制字符全部写成 \uXXXX——两种写法解码后是同一文字。
49	func cliSpecialJSON(t *testing.T, spelling, s string) string {
50		t.Helper()
51		switch spelling {
52		case "direct":
53			b, err := json.Marshal(s)
54			if err != nil {
55				t.Fatalf("marshal %q: %v", s, err)
56			}
57			return string(b)
58		case "escaped":
59			return `"` + escapeJSONString(s) + `"`
