67	// 不成立（两个条件的逐条判断都要保留），r-定案🚀 命中并返回 false 定案，
68	// r-隐身 不再被考虑。所有名称与比较内容都含中文、重音字符与表情。
69	func cliSpecialConfig(t *testing.T, spelling string) string {
