76			`{"id":` + j(cliSpecialRuleDecide) + `,"value":false,"conditions":[` +
77			`{"attribute":` + j("地区") + `,"op":"eq","value":` + j("北京🚀") + `}]},` +
78			`{"id":"r-隐身","value":true,"conditions":[` +
79			`{"attribute":` + j("地区") + `,"op":"eq","value":"上海"}]}]}]}`
80	}
81	
82	// cliSpecialContext 让首条规则因 标签🏷 不命中而整体不成立、第二条规则命中。
83	func cliSpecialContext(t *testing.T, spelling string) string {
84		t.Helper()
