91	// TestCLIExplainSpecialStringsEndToEnd 验证直接字符与合法 \uXXXX 转义表示同一
92	// 文字时，配置与上下文各自独立地选任一写法都选中同一开关、查找同一属性、得到
93	// 相同判断：解释里的 attribute、compareValue、actualValue 与 ruleId 保留解码
94	// 后的文字，stdout 逐字节一致；同一输入在普通模式与解释模式下 key、value、
95	// reason、ruleId 四项一致。
96	func TestCLIExplainSpecialStringsEndToEnd(t *testing.T) {
97		var reference string
98		for _, cfgSpelling := range []string{"direct", "escaped"} {
99			for _, ctxSpelling := range []string{"direct", "escaped"} {
100				t.Run(cfgSpelling+"-config/"+ctxSpelling+"-context", func(t *testing.T) {
