114					}
115					if got["key"] != cliSpecialKey || got["value"] != false ||
116						got["reason"] != "rule" || got["ruleId"] != cliSpecialRuleDecide {
117						t.Fatalf("unexpected payload: %v", got)
118					}
119	
120					rules := rulesOf(t, got)
121					if len(rules) != 2 || rules[0]["ruleId"] != cliSpecialRuleMiss ||
122						rules[1]["ruleId"] != cliSpecialRuleDecide {
123						t.Fatalf("considered rules wrong (r-隐身 must not appear): %v", rules)
124					}
125					if rules[0]["match"] != false || rules[1]["match"] != true {
126						t.Fatalf("match flags wrong: %v", rules)
127					}
128					// 首条未命中规则的全部条件判断保留，文字为解码后的内容。
129					conds := rules[0]["conditions"].([]any)
130					if len(conds) != 2 {
131						t.Fatalf("missed rule must keep all condition records: %v", conds)
132					}
133					plan := conds[0].(map[string]any)
134					if plan["attribute"] != "套餐é" || plan["compareValue"] != "专业版 🚀" ||
135						plan["actualValue"] != "专业版 🚀" || plan["missing"] != false || plan["match"] != true {
136						t.Fatalf("plan condition must hold decoded text: %v", plan)
137					}
138					tag := conds[1].(map[string]any)
139					list := tag["compareValue"].([]any)
140					if len(list) != 4 || list[0] != "" || list[1] != "中文" || list[2] != "中文" || list[3] != "café 🚀" {
141						t.Fatalf("in list must keep empty member, duplicates and order: %v", list)
142					}
143					if tag["attribute"] != "标签🏷" || tag["actualValue"] != "其他" ||
144						tag["missing"] != false || tag["match"] != false {
145						t.Fatalf("tag condition should be a present non-member: %v", tag)
146					}
147					decide := rules[1]["conditions"].([]any)[0].(map[string]any)
148					if decide["attribute"] != "地区" || decide["compareValue"] != "北京🚀" ||
149						decide["actualValue"] != "北京🚀" || decide["match"] != true {
150						t.Fatalf("deciding condition must hold decoded text: %v", decide)
151					}
152	
153					// 同一输入的普通模式：key/value/reason/ruleId 四项必须一致。
154					var pout, perr bytes.Buffer
155					if code := run(h.evalArgs(cliSpecialKey), &pout, &perr); code != 0 {
156						t.Fatalf("plain exit=%d stderr=%s", code, perr.String())
157					}
158					var plain map[string]any
159					if err := json.Unmarshal(pout.Bytes(), &plain); err != nil {
160						t.Fatalf("plain stdout is not JSON: %v (%q)", err, pout.String())
161					}
162					for _, k := range []string{"key", "value", "reason", "ruleId"} {
163						if plain[k] != got[k] {
164							t.Fatalf("field %s differs: plain=%v explain=%v", k, plain[k], got[k])
165						}
166					}
167	
168					if reference == "" {
169						reference = out
170					} else if out != reference {
171						t.Fatalf("spelling changed explain output:\n%s\n!= reference:\n%s", out, reference)
172					}
173				})
174			}
175		}
176	}
