178	// TestCLIExplainKeyArgumentStaysLiteral 验证命令行开关键按字面查找：反斜杠加
179	// u 和数字组成的普通文本不能再次解码，也不与对应的真实字符混为一谈；解释里
180	// 的 ruleId 同样保持字面文本。
181	func TestCLIExplainKeyArgumentStaysLiteral(t *testing.T) {
182		// 第一个开关的 key/id 都是带反斜杠的普通文本（JSON "\\u00E9" 解码为
183		// 普通文本 u00E9）；若被再次解码，两个开关的 key 都会变成 "café"。
184		config := `{"flags":[
185			{"key":"caf\\u00E9","enabled":true,"default":false,"rules":[
186				{"id":"r-\\uD83D\\uDE80","value":true,"conditions":[
187					{"attribute":"plan","op":"eq","value":"pro"}]}]},
188			{"key":"café","enabled":true,"default":true,"rules":[]}]}`
189		h := newHarness(t, config, `{"plan":"pro"}`)
190	
191		// 字面文本 key 选中字面文本开关；解释里的 ruleId 保持字面文本，不变成 🚀。
192		literalKey := `caf\u00E9`
193		literalID := `r-\uD83D\uDE80`
194		got := explainSuccess(t, h, literalKey)
195		if got["key"] != literalKey || got["value"] != true ||
196			got["reason"] != "rule" || got["ruleId"] != literalID {
197			t.Fatalf("literal key must select the literal flag: %v", got)
198		}
199		rules := rulesOf(t, got)
200		if len(rules) != 1 || rules[0]["ruleId"] != literalID {
201			t.Fatalf("explanation must keep the literal rule id: %v", rules)
202		}
203	
204		// 真实字符 key 选中另一个开关：二者互不混同。
205		got = explainSuccess(t, h, "café")
206		if got["key"] != "café" || got["value"] != true ||
207			got["reason"] != "default" || got["ruleId"] != nil {
208			t.Fatalf("decoded key must select the real café flag: %v", got)
209		}
210	}
