212	// TestCLIExplainQuotesBackslashControlSingleLine 验证引号、反斜杠以及合法转义
213	// 表示的换行和制表符进入字符串后：成功输出仍是单行、可解析的一个 JSON 对象；
214	// 读取输出得到的文字与输入解码后的内容相同，不丢字符、不重复转义，字符串
215	// 内容也不会变成新字段。
216	func TestCLIExplainQuotesBackslashControlSingleLine(t *testing.T) {
217		attr := "属\"性\\名"
218		value := "行一\n行二\t制表\"引号\\反斜杠🚀"
219		ruleID := "r-引号\"反斜杠\\"
220		js := func(s string) string {
221			b, err := json.Marshal(s)
222			if err != nil {
223				t.Fatalf("marshal %q: %v", s, err)
224			}
225			return string(b)
226		}
227		config := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[` +
228			`{"id":` + js(ruleID) + `,"value":true,"conditions":[` +
229			`{"attribute":` + js(attr) + `,"op":"eq","value":` + js(value) + `},` +
230			`{"attribute":"标签","op":"in","value":["",` + js(value) + `,` + js(value) + `]}]}]}]}`
231		context := `{` + js(attr) + `:` + js(value) + `,"标签":` + js(value) + `}`
232		h := newHarness(t, config, context)
233	
234		var stdout, stderr bytes.Buffer
235		if code := run(h.evalExplainArgs("f"), &stdout, &stderr); code != 0 {
236			t.Fatalf("exit=%d stderr=%s", code, stderr.String())
237		}
238		out := strings.TrimSpace(stdout.String())
239		if strings.Contains(out, "\n") {
240			t.Fatalf("output must stay a single line: %q", out)
241		}
242		var got map[string]any
243		if err := json.Unmarshal([]byte(out), &got); err != nil {
244			t.Fatalf("output is not one parseable JSON object: %v (%q)", err, out)
245		}
246		// 字符串内容不得变成新字段：顶层恰好五个既有字段。
247		if len(got) != 5 {
248			t.Fatalf("top-level fields changed by string content: %v", got)
249		}
250		for _, k := range []string{"key", "value", "reason", "ruleId", "explanation"} {
251			if _, ok := got[k]; !ok {
252				t.Fatalf("missing field %q in %v", k, got)
253			}
254		}
255		// 读回的文字与输入解码后的内容相同：不丢字符、不重复转义。
256		if got["ruleId"] != ruleID {
257			t.Fatalf("ruleId decoded text wrong: %q want %q", got["ruleId"], ruleID)
258		}
259		rules := rulesOf(t, got)
260		if rules[0]["ruleId"] != ruleID {
261			t.Fatalf("explanation ruleId decoded text wrong: %q want %q", rules[0]["ruleId"], ruleID)
262		}
263		conds := rules[0]["conditions"].([]any)
264		c0 := conds[0].(map[string]any)
265		if c0["attribute"] != attr || c0["compareValue"] != value || c0["actualValue"] != value {
266			t.Fatalf("decoded text drifted: %v", c0)
267		}
268		if len(c0) != 6 {
269			t.Fatalf("condition fields changed by string content: %v", c0)
270		}
271		c1 := conds[1].(map[string]any)
272		list := c1["compareValue"].([]any)
273		if len(list) != 3 || list[0] != "" || list[1] != value || list[2] != value {
274			t.Fatalf("in list must keep empty member, duplicates and order: %v", list)
275		}
276	}
277	
278	// TestCLIExplainSpecialAttrMissingVsEmpty 验证含特殊字符的属性名准确区分缺失
279	// 与空值：未提供时 actualValue 为 null、missing 为 true；显式空字符串保留空
280	// 字符串、missing 为 false。属性名的转义写法与直接字符查找同一属性。
281	func TestCLIExplainSpecialAttrMissingVsEmpty(t *testing.T) {
282		// 配置里的属性名用代理项对转义写法（"标签🏷"），上下文里直接书写字符。
283		config := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
284			{"id":"r","value":true,"conditions":[
285				{"attribute":"标签\uD83C\uDFF7","op":"eq","value":""}]}]}]}`
286	
287		h := newHarness(t, config, `{}`)
288		got := explainSuccess(t, h, "f")
289		c := rulesOf(t, got)[0]["conditions"].([]any)[0].(map[string]any)
290		if c["attribute"] != "标签🏷" || c["missing"] != true || c["actualValue"] != nil || c["match"] != false {
291			t.Fatalf("missing special attribute must be null/true: %v", c)
292		}
293	
294		h = newHarness(t, config, `{"标签🏷":""}`)
295		got = explainSuccess(t, h, "f")
296		c = rulesOf(t, got)[0]["conditions"].([]any)[0].(map[string]any)
297		if c["missing"] != false || c["actualValue"] != "" || c["match"] != true {
298			t.Fatalf("explicit empty string must be kept with missing=false: %v", c)
299		}
300		if got["reason"] != "rule" || got["value"] != true {
301			t.Fatalf("empty string must match eq \"\": %v", got)
302		}
303	}
304	
305	// TestCLIExplainInvalidSurrogateRejected 验证不能组成完整字符的代理项转义在
306	// 解释模式下继续按现有约定拒绝：非零退出、标准输出为空（不留半份解释），
307	// 标准错误指出问题所属位置和转义不完整的原因。
308	func TestCLIExplainInvalidSurrogateRejected(t *testing.T) {
309		const incomplete = "does not form a complete character"
310		goodCfg := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
311			{"id":"r","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"pro"}]}]}]}`
312		cases := []struct {
313			name    string
314			config  string
315			context string
316			wantSub []string
317		}{
318			{
319				"config eq value lone high surrogate",
320				`{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
321					{"id":"r","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"\uD800"}]}]}]}`,
322				`{"plan":"pro"}`,
323				[]string{`config.flags[0].rules[0].conditions[0].value`, `\uD800`, incomplete},
324			},
325			{
326				"config in-list lone low surrogate",
327				`{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
328					{"id":"r","value":true,"conditions":[{"attribute":"plan","op":"in","value":["ok","\uDC00"]}]}]}]}`,
329				`{"plan":"ok"}`,
330				[]string{`config.flags[0].rules[0].conditions[0].value[1]`, `\uDC00`, incomplete},
331			},
332			{
333				"config field name surrogate",
334				`{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],"met\uD800a":1}]}`,
335				`{}`,
336				[]string{`config.flags[0]`, `\uD800`, incomplete},
337			},
338			{
339				"context value surrogate",
340				goodCfg, `{"plan":"\uD800"}`,
341				[]string{`context.plan`, `\uD800`, incomplete},
342			},
343			{
344				"context field name surrogate",
345				goodCfg, `{"pl\uDC00an":"pro"}`,
346				[]string{`context`, `\uDC00`, incomplete},
347			},
348		}
349		for _, tc := range cases {
350			t.Run(tc.name, func(t *testing.T) {
351				h := newHarness(t, tc.config, tc.context)
352				var stdout, stderr bytes.Buffer
353				if code := run(h.evalExplainArgs("f"), &stdout, &stderr); code == 0 {
354					t.Fatalf("expected non-zero exit, stdout=%q", stdout.String())
355				}
356				if stdout.Len() != 0 {
357					t.Fatalf("stdout must be empty (no half explanation): %q", stdout.String())
358				}
359				for _, want := range tc.wantSub {
360					if !strings.Contains(stderr.String(), want) {
361						t.Fatalf("stderr=%q, want substring %q", stderr.String(), want)
362					}
363				}
364			})
365		}
366	}
