// 必填 default 字段的开关 half。half 既不会被选中也已关闭，但整份配置仍须
// 完整校验，它的缺失字段必须最先被报告，位置指向 flags[1]。
const precedenceBrokenConfig = `{"flags":[
	{"key":"off","enabled":false,"default":false,"rules":[]},
	{"key":"half","enabled":false,"rules":[]}]}`

